//! Generated files: man pages, completion files, the command reference.

use std::fmt::Write;

use anyhow::Result;
use clap::{Arg, Command, CommandFactory};

use crate::args::{Cli, Generate};
use crate::shell;

pub fn run(what: Generate) -> Result<()> {
    match what {
        Generate::Man { dir } => {
            std::fs::create_dir_all(&dir)?;
            clap_mangen::generate_to(Cli::command(), &dir)?;
        }
        Generate::Completion { shell } => print!("{}", shell::completion_file(shell)?),
        Generate::Markdown => print!("{}", markdown()),
    }
    Ok(())
}

/// The command reference page of the documentation.
fn markdown() -> String {
    let mut cmd = Cli::command();
    cmd.build();

    let mut out = String::new();
    out.push_str("# Command reference\n\n");
    out.push_str("<!-- Generated by `wtm generate markdown`; do not edit. -->\n\n");
    if let Some(about) = cmd.get_long_about() {
        let _ = writeln!(out, "{about}\n");
    }

    out.push_str("## Global options\n\n");
    out.push_str("These apply to all commands.\n\n");
    let globals: Vec<&Arg> = cmd
        .get_arguments()
        .filter(|a| shown(a) && a.is_global_set())
        .collect();
    write_args(&mut out, &globals);

    for sub in cmd.get_subcommands().filter(|s| !s.is_hide_set()) {
        write_command(&mut out, sub, 2);
    }
    out
}

fn shown(arg: &Arg) -> bool {
    !arg.is_hide_set() && !matches!(arg.get_id().as_str(), "help" | "version")
}

fn write_command(out: &mut String, cmd: &Command, level: usize) {
    let name = cmd.get_bin_name().unwrap_or(cmd.get_name());
    let _ = writeln!(out, "{} {name}\n", "#".repeat(level));
    if let Some(about) = cmd.get_long_about().or(cmd.get_about()) {
        let _ = writeln!(out, "{about}\n");
    }
    for alias in cmd.get_visible_aliases() {
        let _ = writeln!(out, "Alias: `{alias}`\n");
    }

    if cmd.has_subcommands() {
        for sub in cmd.get_subcommands().filter(|s| !s.is_hide_set()) {
            write_command(out, sub, level + 1);
        }
        return;
    }

    let usage = cmd.clone().render_usage().to_string();
    let usage = usage.trim_start_matches("Usage: ");
    let _ = writeln!(out, "```\n{usage}\n```\n");

    let args: Vec<&Arg> = cmd
        .get_arguments()
        .filter(|a| shown(a) && !a.is_global_set())
        .collect();
    let positional: Vec<&Arg> = args.iter().copied().filter(|a| a.is_positional()).collect();
    let options: Vec<&Arg> = args
        .iter()
        .copied()
        .filter(|a| !a.is_positional())
        .collect();
    if !positional.is_empty() {
        out.push_str("Arguments:\n\n");
        write_args(out, &positional);
    }
    if !options.is_empty() {
        out.push_str("Options:\n\n");
        write_args(out, &options);
    }
}

fn write_args(out: &mut String, args: &[&Arg]) {
    for arg in args {
        let help = arg
            .get_long_help()
            .or(arg.get_help())
            .map(|h| h.to_string().replace('\n', " "))
            .unwrap_or_default();
        let mut line = format!("- `{}` — {help}", arg_label(arg));
        let possible: Vec<String> = arg
            .get_possible_values()
            .iter()
            .filter(|v| !v.is_hide_set())
            .map(|v| format!("`{}`", v.get_name()))
            .collect();
        if arg.is_positional() && !possible.is_empty() {
            let _ = write!(line, " One of: {}.", possible.join(", "));
        }
        let defaults: Vec<String> = arg
            .get_default_values()
            .iter()
            .map(|v| format!("`{}`", v.to_string_lossy()))
            .collect();
        if !defaults.is_empty() {
            let _ = write!(line, " (default: {})", defaults.join(", "));
        }
        let _ = writeln!(out, "{}", line.trim_end());
    }
    out.push('\n');
}

fn arg_label(arg: &Arg) -> String {
    let value = arg
        .get_value_names()
        .and_then(|names| names.first())
        .map(|n| n.to_string())
        .unwrap_or_else(|| arg.get_id().as_str().to_uppercase());
    if arg.is_positional() {
        let label = format!("<{value}>");
        return if arg.is_required_set() {
            label
        } else {
            format!("[{label}]")
        };
    }
    let mut label = String::new();
    if let Some(short) = arg.get_short() {
        let _ = write!(label, "-{short}, ");
    }
    if let Some(long) = arg.get_long() {
        let _ = write!(label, "--{long}");
    }
    if arg.get_action().takes_values() {
        let _ = write!(label, " <{value}>");
    }
    label
}
